SELECT ?subject ?label ?maker ?makerLabel WHERE {
  ?subject ?labelProp ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "ecce homo"))
  OPTIONAL {
    ?subject ?makerProp ?maker .
    FILTER(CONTAINS(LCASE(STR(?makerProp)), "maker") || CONTAINS(LCASE(STR(?makerProp)), "creator") || CONTAINS(LCASE(STR(?makerProp)), "author"))
    OPTIONAL { ?maker ?lp ?makerLabel . FILTER(CONTAINS(LCASE(STR(?lp)), "label")) }
  }
}

